#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ColorSpace {
    /// sRGB (default web)
    Srgb,
    /// Linear sRGB
    SrgbLinear,
    /// Display P3 (wide gamut)
    DisplayP3,
    /// Adobe RGB (1998)
    A98Rgb,
    /// ProPhoto RGB
    ProphotoRgb,
    /// ITU-R Rec. 2020
    Rec2020,
    /// CIE XYZ (D50 white point)
    Xyz,
    /// CIE Lab
    Lab,
    /// CIE LCh
    Lch,
    /// OK Lab
    Oklab,
    /// OK LCh
    Oklch,
    /// CIE XYZ D50
    XyzD50,
    /// CIE XYZ D65
    XyzD65,
}

