/// A CSS color value.
#[derive(Debug, Clone, PartialEq)]
pub enum CssColor {
    Named(NamedColor),
    Rgb { r: f64, g: f64, b: f64, alpha: f64 },
    Hsl { h: f64, s: f64, l: f64, alpha: f64 },
    Hwb { h: f64, w: f64, b: f64, alpha: f64 },
    Lab { l: f64, a: f64, b: f64, alpha: f64 },
    Lch { l: f64, c: f64, h: f64, alpha: f64 },
    Oklab { l: f64, a: f64, b: f64, alpha: f64 },
    Oklch { l: f64, c: f64, h: f64, alpha: f64 },
    Generic { space: ColorSpace, components: [f64; 3], alpha: f64 },
    CurrentColor,
    Transparent,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InterpolationSpace {
    Oklch,
    Oklab,
    Lab,
    Lch,
    Srgb,
    SrgbLinear,
    Hsl,
    Hwb,
}

/// Color mix operation.
#[derive(Debug, Clone)]
pub struct ColorMix {
    pub space: InterpolationSpace,
    pub color1: CssColor,
    pub color2: CssColor,
    pub percentage: f64, // 0.0 = color1, 1.0 = color2
}